Iterable<java.awt.image.BufferedImage> lazyThumbnails = net.coobird.thumbnailator.Thumbnails.of(sourceImage, sourceImage, sourceImage)
    .size(50, 50)
    .iterableBufferedImages();

int count = 0;
int maxDim = 0;
for (java.awt.image.BufferedImage img : lazyThumbnails) {
    if (img != null) {
        count++;
        maxDim = Math.max(maxDim, Math.max(img.getWidth(), img.getHeight()));
    }
}

assert count == 3 : "Expected exactly 3 thumbnails to be generated";
assert maxDim > 0 && maxDim <= 50 : "Expected max dimension to be bounded by 50";

System.out.println("__CHECK__ iterableBufferedImages " + count + "," + maxDim);

